// The claims register: every card, procedure and exercise the guide ships, with each claim, its
// confidence and its sources, as one document for the captain to read, correct or strike.
// Generated by `npm run guide:dossier` into docs/TRAINING-CLAIMS.md; `npm test` fails when it is stale.
import type { Claim, Content, Source, Track } from './types';

const NAMES: Record<Track, string> = { azipod: 'Azipod ships', tugs: 'Tugs', special: 'Specialised propulsion' };

export function renderClaims(c: Content, sources: Source[]): string {
  const all = [...c.cards, ...c.procedures, ...c.exercises];
  const draft = all.filter(x => x.review === 'draft').length;
  const o: string[] = [
    '# Training guide: claims register',
    '',
    'Generated from `src/guide/content` by `npm run guide:dossier`. Do not edit by hand: `npm test` fails when it is out of date.',
    'The sources are listed in [TRAINING.md](TRAINING.md). Numbers written as `{token}` are filled in from the ship\'s own particulars or a published figure.',
    '',
    `**${c.cards.length} cards · ${c.procedures.length} procedures · ${c.exercises.length} exercises · ${draft} draft · ${all.length - draft} reviewed**`,
    '',
  ];
  const claim = (cl: Claim) => `  - \`${cl.conf}\` ${cl.text}${cl.src.length ? ` — *${cl.src.join(', ')}*` : ''}`;
  for (const t of ['azipod', 'tugs', 'special'] as Track[]) {
    const cards = c.cards.filter(x => x.track === t), procs = c.procedures.filter(x => x.track === t), exs = c.exercises.filter(x => x.track === t);
    o.push(`## ${NAMES[t]}`, '');
    if (!cards.length && !procs.length && !exs.length) o.push('Nothing shipped yet.', '');
    for (const k of cards) {
      o.push(`### \`${k.id}\` · ${k.title} · ${k.review}`, '', `Applies to: ${k.fam.join(', ')}${k.ships ? ` (${k.ships.join(', ')})` : ''}${k.tip ? ` · tip when \`${k.tip.when}\` (hold ${k.tip.hold} s, cool ${k.tip.cool} s, priority ${k.tip.prio})` : ''}`, '');
      o.push(`- **Brief:** ${k.brief}`);
      if (k.why) o.push(`- **Why:** ${k.why}`);
      if (k.real.length) o.push('- **Real world:**', ...k.real.map(claim));
      if (k.sim) o.push(`- **In SHIPSHAPE:** ${k.sim}`);
      o.push('');
    }
    for (const p of procs) {
      o.push(`### \`${p.id}\` · ${p.title} · procedure · ${p.review}`, '', `Applies to: ${p.fam.join(', ')}${p.ships ? ` (${p.ships.join(', ')})` : ''} · proof \`${p.proof}\`${p.minKn ? ` · needs ${p.minKn} kn` : ''}`, '', `- **Brief:** ${p.brief}`);
      p.steps.forEach((s, i) => o.push(`  ${i + 1}. ${s.text}${s.why ? ` — ${s.why}` : ''} (check \`${s.check}\`)`));
      if (p.real.length) o.push('- **Real world:**', ...p.real.map(claim));
      if (p.sim) o.push(`- **In SHIPSHAPE:** ${p.sim}`);
      o.push('');
    }
    for (const e of exs) {
      o.push(`### \`${e.id}\` · ${e.title} · exercise · ${e.review}`, '', `${e.ship} in \`${e.scenario}\`${e.kn ? ` at ${e.kn} kn` : ''} · measured from ${e.begin === 'order' ? 'the first order' : 'the start'} ${e.end === 'time' ? `for ${e.limit} s` : `until she has ${e.end}, at most ${e.limit} s`}`, '', `- **Brief:** ${e.brief}`, ...e.objectives.map(x => `  - ${x}`), `- **Debrief:** ${e.metrics.join(', ')}`);
      if (e.real.length) o.push('- **Real world:**', ...e.real.map(claim));
      o.push('');
    }
  }
  o.push('## Sources cited', '');
  const used = new Set<string>();
  for (const x of [...c.cards, ...c.procedures, ...c.exercises]) for (const cl of x.real) cl.src.forEach(s => used.add(s));
  const cited = sources.filter(s => used.has(s.id));
  o.push(cited.length ? cited.map(s => `- \`${s.id}\` ${s.cite}${s.url ? ` <${s.url}>` : ''}`).join('\n') : 'None yet.', '');
  return o.join('\n');
}
